PREFIX : <https://w3id.org/rastro/ontology#>
SELECT ?name WHERE {
  {
    SELECT ?s (COUNT(DISTINCT ?t) AS ?n) WHERE {
      ?t a :Trial ; :sponsor ?s ; :status ?st ; :testsDrug ?d .
      FILTER(?st IN ("TERMINATED", "WITHDRAWN"))
      ?s :industry true .
      ?d :hasTarget ?tg . ?tg :gene ?g .
      FILTER(?g IN ("EGFR", "ERBB2", "ERBB3", "ERBB4"))
    }
    GROUP BY ?s
  }
  ?s :name ?name .
}
ORDER BY DESC(?n)
LIMIT 1
